<?php
declare(strict_types=1);require_once __DIR__.'/../includes/functions.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);if($id===(int)current_user()['id']){flash('warning','For safety, you cannot change your own admin role or active status here.');redirect('admin/users.php');}$role=$_POST['role']??'user';$active=isset($_POST['is_active'])?1:0;if(!in_array($role,['user','admin'],true))$role='user';db()->prepare('UPDATE users SET role=?,is_active=? WHERE id=?')->execute([$role,$active,$id]);audit('ADMIN_USER_UPDATE',$id,'role='.$role.',active='.$active);flash('success','User permissions updated.');redirect('admin/users.php');}
$items=db()->query('SELECT u.*,COUNT(DISTINCT r.id) recipe_count,COUNT(DISTINCT f.id) saved_count FROM users u LEFT JOIN recipes r ON r.author_id=u.id LEFT JOIN favorites f ON f.user_id=u.id GROUP BY u.id ORDER BY u.created_at DESC')->fetchAll();$pageTitle='Manage users';require __DIR__.'/../includes/header.php';?>
<section class="admin-head"><div class="container"><span class="eyebrow light">Access control</span><h1>Users & roles</h1><nav class="admin-tabs"><a href="<?=e(url('admin/index.php'))?>">Overview</a><a href="<?=e(url('admin/recipes.php'))?>">Recipes</a><a href="<?=e(url('admin/comments.php'))?>">Comments</a><a class="active" href="<?=e(url('admin/users.php'))?>">Users</a><a href="<?=e(url('admin/settings.php'))?>">Settings</a><a href="<?=e(url('admin/audit.php'))?>">Audit log</a></nav></div></section>
<section class="section container"><div class="table-wrap"><table><thead><tr><th>User</th><th>Activity</th><th>Role & access</th></tr></thead><tbody><?php foreach($items as $u):?><tr><td><strong><?=e($u['display_name'])?></strong><small><?=e($u['email'])?> · Joined <?=e(date('j M Y',strtotime($u['created_at'])))?></small></td><td><?=$u['recipe_count']?> recipes · <?=$u['saved_count']?> saves</td><td><?php if($u['id']==current_user()['id']):?><span class="status status-approved">Current admin</span><?php else:?><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=$u['id']?>"><select name="role"><option value="user" <?=$u['role']==='user'?'selected':''?>>User</option><option value="admin" <?=$u['role']==='admin'?'selected':''?>>Admin</option></select><label class="checkbox"><input type="checkbox" name="is_active" <?=$u['is_active']?'checked':''?>> Active</label><button class="button button-small button-secondary">Update</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
